<?php
require_once __DIR__ . '/config.php';
try { $count = (int)db()->query('SELECT COUNT(*) FROM admin_users')->fetchColumn(); }
catch (Throwable $e) { http_response_code(500); exit('Database is not ready. Configure config.php and import sql/schema.sql first.'); }
if ($count > 0) { http_response_code(403); exit('An admin account already exists. For security, delete setup.php from your hosting account.'); }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $username = trim((string)($_POST['username'] ?? '')); $password = (string)($_POST['password'] ?? ''); $confirm = (string)($_POST['confirm_password'] ?? '');
    if (!preg_match('/^[A-Za-z0-9_.-]{4,80}$/', $username)) $error = 'Username must be 4–80 characters using letters, numbers, dots, underscores, or hyphens.';
    elseif (strlen($password) < 12) $error = 'Use a password of at least 12 characters.';
    elseif ($password !== $confirm) $error = 'Passwords do not match.';
    else { $stmt=db()->prepare('INSERT INTO admin_users (username,password_hash) VALUES (?,?)'); $stmt->execute([$username,password_hash($password,PASSWORD_DEFAULT)]); flash('success','Admin account created. Sign in to manage your portfolio.'); redirect('admin/login.php'); }
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Initial setup · Shihab Portfolio</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="admin-body"><main class="setup-card"><a class="brand" href="index.php"><span class="brand-mark">S.</span><span>SHIHAB<span class="brand-dot">/</span></span></a><h1>Create your admin account</h1><p>This one-time setup creates the login used to manage your portfolio.</p><?php if($error): ?><div class="flash flash-error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Admin username<input name="username" required minlength="4" maxlength="80" autocomplete="username"></label><label>Password (12+ characters)<input type="password" name="password" required minlength="12" autocomplete="new-password"></label><label>Confirm password<input type="password" name="confirm_password" required minlength="12" autocomplete="new-password"></label><button class="button button-primary" type="submit">Create admin account ↗</button></form><p class="setup-warning">After creating the account, delete <code>setup.php</code> from your hosting File Manager.</p></main><style>.setup-card{width:min(460px,calc(100% - 30px));margin:8vh auto;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:30px}.setup-card h1{font:600 28px 'Space Grotesk';margin:30px 0 5px}.setup-card p{font-size:13px;color:var(--muted)}.setup-card label{display:block;font-size:12px;margin:18px 0}.setup-card input{display:block;width:100%;margin-top:7px;padding:12px;border-radius:8px;border:1px solid var(--line);background:var(--bg);color:var(--text)}.setup-card button{width:100%}.setup-warning{border-top:1px solid var(--line);padding-top:15px;margin-top:24px!important}</style></body></html>
